require 'pathname'
require 'sprockets'

# Concatenates the legacy admin JavaScript (app/legacy_js) and the jQuery libraries it depends on into the
# prebuilt script that ships with the gem. Hosts never compile Fae's JavaScript, so this runs on the
# maintainer's machine only. Sprockets does the resolving here, which keeps the bundled library versions
# tied to this repo's Gemfile.lock.
module FaeJsBuilder
  ROOT = Pathname.new(File.expand_path('..', __dir__))
  SOURCE_DIR = ROOT.join('app/legacy_js')
  ENTRY = 'fae/application.js'.freeze
  OUTPUT = ROOT.join('app/assets/builds/fae_admin.js')

  # Gems that provide files the entry point requires (jquery, jquery_ujs, jquery-ui widgets, judge, json2, remotipart)
  ASSET_GEMS = %w[jquery-rails jquery-ui-rails judge remotipart].freeze

  BANNER = "/* Generated by `rake fae:js:build` from app/legacy_js. Do not edit. */\n".freeze

  def self.environment
    env = Sprockets::Environment.new(ROOT.to_s)
    env.cache = nil
    env.js_compressor = nil
    env.append_path(SOURCE_DIR.to_s)

    ASSET_GEMS.each do |name|
      gem_dir = Pathname.new(Gem.loaded_specs.fetch(name).full_gem_path)
      %w[app lib vendor].each do |base|
        path = gem_dir.join(base, 'assets/javascripts')
        env.append_path(path.to_s) if path.directory?
      end
    end

    env
  end

  def self.compile
    asset = environment.find_asset(ENTRY) or raise "Couldn't resolve #{ENTRY} from #{SOURCE_DIR}"
    # Vendored libraries reference source maps we don't ship; Sprockets only strips these when loaded by Rails
    BANNER + asset.source.gsub(%r{^//# sourceMappingURL=.*$}, '')
  end

  def self.build
    OUTPUT.dirname.mkpath
    OUTPUT.write(compile)
    OUTPUT
  end

  def self.current?
    OUTPUT.exist? && OUTPUT.read == compile
  end

  def self.sources
    Dir[SOURCE_DIR.join('**/*')].select { |f| File.file?(f) }
  end
end
